(()=>{const images=document.querySelectorAll('.deferred-photo');if(!('IntersectionObserver'in window)){images.forEach(e=>e.classList.add('photo-ready'));return}const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('photo-ready');observer.unobserve(entry.target)}})},{rootMargin:'400px 0px'});images.forEach(e=>observer.observe(e));if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const reveal=new IntersectionObserver(entries=>{let delay=0;for(const entry of entries){if(!entry.isIntersecting)continue;const el=entry.target;reveal.unobserve(el);if(el.animate&&!el.contains(document.activeElement)){el.animate([{opacity:0,transform:'translateY(22px)'},{opacity:1,transform:'translateY(0)'}],{duration:550,delay,fill:'backwards',easing:'cubic-bezier(.2,.65,.3,1)'});delay=Math.min(delay+65,195)}}},{threshold:0,rootMargin:'0px 0px -24px 0px'});document.querySelectorAll('.story-layout > div > *, .closing .reveal > *, .footer-grid > *, .category-heading, .product').forEach(el=>reveal.observe(el))}})();